"""Eight Cults source versions, compared benefit by benefit with the Guide.
Differences remain in the selected source version rather than being merged away.
"""
import json,copy
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;directory=repo/'scripts/reviewed-content'
rows=[(220,'bankers-of-dunsirn',['O Dinheiro Ofusca','O Dinheiro é Eloquente','O Dinheiro Proporciona','Dinheiro Atrai Dinheiro','O Dinheiro Manda']), (221,'children-of-tenochtitlan',['Escondido do Lobo','Instintos de Fantasma','Visão do Futuro','Necromante Prodígio','Próximo da Fila']), (222,'nasyon-san-an',['Coisas de CSI','Cadáver Requintado','Oco por Dentro','Meu Amigo Setita','O Chapéu de Seda']), (223,'flesh-eaters',['Víscera','Espírito Invisível','O Assassinato Perfeito','Encontrar Assassino','Mordida Monstruosa']), (224,'harbingers-of-ashur',['Máscara de Freixo','Máscara de Ouro','Máscara Branca','Máscara de Obsidiana','Máscara de Lázaro']), (225,'la-famiglia-giovanni',['Coisa de Primo','Resquício de Glamour','Dinheiro Trocado','Servo Espectral','Aspirante a Anziani']), (227,'the-gorgons',['O Beijo da Serpente','Proteção','Quatro Humores','Controlando a Besta','Olhar da Medusa'])]
general={locale:json.loads((directory/'bloodline-bankers-of-dunsirn.json').read_text(encoding='utf-8'))['versions'][0]['descriptions'][locale][-1] for locale in ['pt-BR','en']}
for page,slug,titles in rows:
 file=directory/f'bloodline-{slug}.json';entry=json.loads(file.read_text(encoding='utf-8'));guide=[v for v in entry['versions'] if v['book']=='players-guide-v5'];assert len(guide)==5;versions=[]
 for old,title in zip(guide,titles):
  v=copy.deepcopy(old);rank=v['level'];v['id']=f'{entry["id"]}-cultos-deuses-sangue-v5-{rank}';v['book']='cultos-deuses-sangue-v5';v['sourceLanguage']='pt-BR';v['pages']=[{'pdfPage':page,'printedPage':page},{'pdfPage':219,'printedPage':219}];v['sourceTitle']=f'Cultos dos Deuses de Sangue V5, p. {page} · {rank}';v.pop('pdfSha256',None)
  name_pt='Descendentes do Barão' if slug=='nasyon-san-an' else entry['names']['pt-BR'];name_en='Descendants of the Baron' if slug=='nasyon-san-an' else entry['names']['en'];body={locale:v['descriptions'][locale][1]['text'] for locale in ['pt-BR','en']}
  if slug=='nasyon-san-an':
   if rank==1:body['pt-BR']=body['pt-BR'].replace('Como aspirante a gede','Como cria do Barão');body['en']=body['en'].replace('As an aspiring gede','As a childe of the Baron')
   if rank==2:body={'pt-BR':'Os Samedi já foram cadáveres ambulantes, mas a Reunião da Família lhes deu novos rostos. Você pode retomar sua aparência cadavérica quando quiser. Uma vez por sessão, assuma a aparência de um cadáver que tocou, com sua podridão e cheiro atuais. Para perceber falhas reveladoras, observadores testam Determinação + Percepção contra dificuldade igual à sua Determinação.','en':'The Samedi once looked like walking corpses, but the Family Reunion gave them new faces. You can resume your corpse-like appearance at will. Once per session, take on the appearance of a corpse you have touched, including its current decay and smell. To spot revealing flaws, observers roll Resolve + Awareness at a Difficulty equal to your Resolve.'}
   if rank==3:body={'pt-BR':'Os filhos do Barão não parecem mais cadáveres, mas alguns conservam vantagens de sê-lo: cadáveres não sentem. Você não sofre a penalidade de dois dados nas paradas relevantes por debilitação física. A penalidade de debilitação de Força de Vontade ainda se aplica.','en':'The Baron’s childer no longer look like corpses, but some retain the advantages of being one: corpses feel nothing. You do not suffer the two-dice penalty to relevant pools from physical Impairment. The penalty from Willpower Impairment still applies.'}
   if rank==5:body={'pt-BR':'Ninguém sabe ao certo quem é o Barão, mas ele o favorece e você é o próximo na sucessão. Não sabe se assumir o chapéu de seda traz apenas um cargo político nos Hecata ou poderes espirituais fantásticos; os inimigos do Barão certamente virão junto. Enquanto não assume, tenha o efeito de Mawla 5, com ajuda enigmática e ações misteriosas.','en':'No one knows precisely who the Baron is, but he favors you and you are next in succession. Claiming his silk hat might bring only a political position among the Hecata or fantastic spiritual powers; it certainly brings the Baron’s enemies. Until you take the role, benefit from Mawla 5, whose help comes through enigmatic means and mysterious actions.'}
  if slug=='flesh-eaters' and rank==1:
   body['pt-BR']+=' A taxa é de um ponto de Fome saciado por ponto de dano causado.';body['en']+=' The rate is one Hunger slaked per point of damage inflicted.'
  if slug=='harbingers-of-ashur' and rank==1:
   body['pt-BR']+=' A Convicção só permanece sem um Pilar mortal enquanto o cadáver original não se decompor a ponto de ser irreconhecível.';body['en']+=' The Conviction remains without a mortal Touchstone only while the original corpse has not decayed beyond recognition.'
  if slug=='la-famiglia-giovanni' and rank==4:body['pt-BR']+=' Nesta fonte, trate o espectro como um Aliado de quatro pontos.';body['en']+=' In this source, treat the wraith as a four-dot Ally.'
  if slug=='the-gorgons' and rank==3:body['pt-BR']=body['pt-BR'].replace('sua Ressonância atual','a Ressonância atual desse mortal')
  if slug=='the-gorgons' and rank==5:
   body={'pt-BR':'As Lamiae mais profundas nos mistérios da linhagem possuem um olhar que torna literal o nome Górgona. Uma vez por sessão, após vencer um teste de Intimidação ou de conflito, os perdedores não conseguem agir no turno seguinte do conflito. Fora de combate, não conseguem se mover por uma cena, a menos que gastem um ponto de Força de Vontade.','en':'The Lamiae most steeped in their bloodline’s mysteries have a gaze that makes the name Gorgon literal. Once per session, after you win an Intimidation or conflict roll, those who lost cannot act on the following conflict turn. Outside combat, they cannot move for one scene unless they spend one Willpower point.'}
  v['names']={'pt-BR':name_pt+' — '+title,'en':name_en+' — '+('Exquisite Corpse' if slug=='nasyon-san-an' and rank==2 else 'Hollow Inside' if slug=='nasyon-san-an' and rank==3 else old['names']['en'].split(' — ',1)[1])}
  v['descriptions']={locale:[{'title':title if locale=='pt-BR' else v['names']['en'].split(' — ',1)[1],'text':body[locale]},general[locale]] for locale in ['pt-BR','en']};versions.append(v)
 entry['versions']=[v for v in entry['versions'] if v['book']!='cultos-deuses-sangue-v5']+versions
 entry['aliases']=list(dict.fromkeys(entry['aliases']+[n for v in versions for n in v['names'].values()]+(['Samedi','Descendentes do Barão','Descendants of the Baron'] if slug=='nasyon-san-an' else [])))
 file.write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
putt=[('Amigos no Submundo','Underworld Friends','Os Puttanesca conhecem as ruas e mantêm atividades paralelas. Receba dois pontos para distribuir entre Aliados e Recursos; pode realocá-los no início de cada história. Essas Vantagens estão sempre sob escrutínio policial.','The Puttanesca know the streets and maintain side businesses. Gain two dots to distribute between Allies and Resources; you may reallocate them at the start of each story. These Advantages are always subject to police scrutiny.'),('Exibindo a Barriguinha','Showing the Belly','Você sobrevive parecendo inofensivo aos poderosos, mesmo que isso seja indigno, para vingar-se depois. Receba três dados em testes para convencer alguém a não feri-lo, colocá-lo em perigo ou agir contra você.','You survive by seeming harmless to the powerful, however undignified, and live to seek revenge later. Gain three dice on rolls to convince someone not to hurt, endanger, or act against you.'),('Erguendo os Punhos','Raising Fists','Nem sempre a submissão funciona. Alguns Puttanesca intimidam os mais fracos para demonstrar autoridade. Contra mortais, receba dois dados em testes de Intimidação e aumente em um seu modificador de dano desarmado.','Submission does not always work. Some Puttanesca bully the weak to show who is in charge. Against mortals, gain two dice on Intimidation tests and increase your unarmed damage modifier by one.'),('Encontro dos Amigos','Gathering Friends','Uma vez por história, reúna uma gangue para uma briga. Inclua quaisquer Membros Puttanesca locais e mortais equivalentes a Aliados 5. Também receba um sucesso automático em testes para convencer outros personagens de que a briga é necessária.','Once per story, gather a gang for a fight. It includes any local Puttanesca Kindred and mortals equivalent to Allies 5. Also gain one automatic success on rolls to convince other characters that the fight is necessary.'),('O Don','The Don','Contra todas as probabilidades, você conquistou respeito, riqueza e influência bajulando e brigando; os Hecata talvez até tenham parado de insultá-lo na sua frente. Você tem três pontos adicionais em Contatos, Influência e Recursos, atribuídos a empreendimentos criminosos. Exigem manutenção cuidadosa para evitar grupos como o FBI, cujos agentes podem se tornar versões potentes do Defeito Inimigo.','Against all odds, flattery and violence earned you respect, wealth, and influence; other Hecata may even have stopped insulting you to your face. You have three additional dots in Contacts, Influence, and Resources, assigned to criminal enterprises. They require careful maintenance to avoid organizations such as the FBI, whose agents can become potent versions of the Enemy Flaw.')]
entry={'id':'bloodline-criminal-puttanesca','kind':'loresheet','names':{'pt-BR':'Puttanesca Criminosos','en':'Criminal Puttanesca'},'aliases':['Puttanesca'],'versions':[]}
for rank,(pt,en,body_pt,body_en) in enumerate(putt,1):
 entry['versions'].append({'id':entry['id']+f'-cultos-deuses-sangue-v5-{rank}','book':'cultos-deuses-sangue-v5','level':rank,'names':{'pt-BR':entry['names']['pt-BR']+' — '+pt,'en':entry['names']['en']+' — '+en},'sourceTitle':f'Cultos dos Deuses de Sangue V5, p. 226 · {rank}','sourceLanguage':'pt-BR','pages':[{'pdfPage':226,'printedPage':226},{'pdfPage':219,'printedPage':219}],'requirements':{'clans':['Hecata'],'loresheetGroup':'bloodline','independentChoice':str(rank),'repeatableDifferentChoices':True,'storytellerApproval':True},'descriptions':{locale:[{'title':pt if locale=='pt-BR' else en,'text':body_pt if locale=='pt-BR' else body_en},general[locale]] for locale in ['pt-BR','en']}})
(directory/(entry['id']+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
print('Eight Cults bloodline versions / 40 benefits; source differences retained, including Samedi and Gorgons.')
